 $('#panels').innerHTML=types.length?types.map((type,i)=>`${i?'<div class="tile-split" role="separator" aria-label="Resize panels" aria-orientation="vertical" tabindex="0"></div>':''}${tile(type,i,'main')}`).join(''):'<div class="empty-page"><span class="eyebrow">A page for your work</span><h2>What would you like here?</h2><p>Add an editor, PDF viewer, plots, or notes.</p><button class="primary" data-action="add-panel">＋ Add a panel</button></div>';
