function tile(type,i,zone){const desc=panelTypes[type]||panelTypes.notes;return `<section class="tile" data-type="${type}" data-index="${i}" data-zone="${zone}"><header class="tile-header" ${arranging?'draggable="true"':''}><span class="drag-handle">⠿</span><strong>${desc[0]}</strong><span class="tile-meta">${tileMeta(type)}</span><div class="tile-actions"><button data-action="focus-panel" title="Fullscreen panel" aria-label="Fullscreen ${desc[0]}">⤢</button><button data-action="remove-panel" title="Remove panel" aria-label="Remove ${desc[0]}">×</button></div></header><div class="tile-body" data-content="${type}"></div><div class="tile-footer">${tileFooter(type)}</div><div class="height-handle" role="separator" aria-label="Resize panel height" tabindex="0" title="Drag to change panel height"></div></section>`}
