function tileFooter(type){return ({editor:'<span data-editor-status>Saved in this browser</span><span style="margin-left:auto">⌘ L / Ctrl L · selection to chat</span>',paper:'Demo renderer · not a LaTeX compiler',curves:'Sample curves · not experimental evidence',compute:'No remote connections or actual GPU launches',diff:'Review applies to browser-local files only',notes:'Saved automatically in this browser',todos:'Download as Markdown from the panel',pdf:'Select text, then use Add to chat',files:'Open a file in the current workspace',board:'Each task owns its workflow and views'})[type]||''}
