function renderChat(){const w=conversation();$('#agent-name').textContent=state.locked?state.lockedName||w.agent:w.agent;$('#lock-agent').classList.toggle('active',state.locked);$('#lock-agent').title=state.locked?'Unlock agent':'Keep this agent while navigating';$('#agent-count').textContent=w.agents.length;$('#agents').innerHTML=w.agents.map(a=>`<button class="agent-row ${a===w.agent?'active':''}" data-agent="${escape(a)}">✧ &nbsp;${escape(a)}</button>`).join('');$('#plan-count').textContent=`${w.todos.filter(t=>t.done).length}/${w.todos.length}`;$('#plan').innerHTML=w.todos.map(t=>`${t.done?'✓':'○'} ${escape(t.text)}`).join('<br>');$('#messages').innerHTML=w.messages.map(messageHTML).join('');$('#chat-suggestions').innerHTML=spec().prompts.map(p=>`<button data-prompt="${escape(p)}">${escape(p)} ↗</button>`).join('');$('#permission').value=state.permission;$('#model').value=state.model;$('#effort').value=state.effort;requestAnimationFrame(()=>{$('#messages').scrollTop=$('#messages').scrollHeight});renderContexts()}
function messageHTML(m){const time=new Date(m.created).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(m.role==='check')return `<details class="message check"><summary>✓ ${escape(m.text)}</summary><p>This is a simulated workflow event. No remote jobs or agents were contacted.</p></details>`;return `<div class="message ${m.role}"><div class="who"><b>${m.role==='user'?'You':escape(conversation().agent)}</b><time>${time}</time></div>${escape(m.text).split('\n\n').map(p=>`<p>${p.replaceAll('\n','<br>')}</p>`).join('')}${m.context?.length?`<span class="pill">${m.context.length} attached selection${m.context.length>1?'s':''}</span>`:''}</div>`}
