function editorMarkup(){return `<div class="editor-tools"><button data-action="editor-files">Files</button><button data-action="terminal">Terminal</button><button data-action="ports">Ports</button><button data-action="show-diff">Agent changes</button><span class="spacer"></span><button data-action="font-minus" title="Smaller text">A−</button><button data-action="font-plus" title="Larger text">A＋</button><button data-action="ask-selection">Add to chat</button><button class="primary" data-action="save-file">Save</button></div><div class="code-location">${escape(spec().path)}/${escape(ws().activeFile)}</div><div class="file-tab">${escape(ws().activeFile)}<span class="dirty-dot"></span><span class="pill">${language(ws().activeFile)}</span><button data-action="copy-path" title="Copy full path">⧉</button></div><div class="monaco-host"></div>`}
