 if(type==='diff'){body.classList.add('editor-body');body.innerHTML=`<div class="diff-summary"><b>train.py</b><span class="plus">+6</span><span class="minus">−1</span><button class="primary" data-action="accept-diff" ${ws().diff!=='pending'?'disabled':''}>Accept</button><button class="outline" data-action="reject-diff" ${ws().diff!=='pending'?'disabled':''}>Reject</button></div><div class="diff-status">${ws().diff==='pending'?'Proposed by the code review worker · not applied':ws().diff==='accepted'?'✓ Accepted · train.py updated in this browser':'Rejected · original file preserved'} ${ws().diff!=='pending'?'<button data-action="reset-diff">Review again</button>':''}</div><div class="monaco-host"></div>`;const m=await getMonaco();if(!el.isConnected||generation!==renderGeneration)return;const original=m.editor.createModel(beforeCode,'python'),modified=m.editor.createModel(afterCode,'python');const editor=m.editor.createDiffEditor($('.monaco-host',el),{theme:state.theme==='dark'?'vs-dark':'vs',automaticLayout:true,renderSideBySide:false,readOnly:true,originalEditable:false,fontSize:12,minimap:{enabled:false},scrollBeyondLastLine:false,wordWrap:'on',hideUnchangedRegions:{enabled:false},padding:{top:10}});editor.setModel({original,modified});editors.push({el,editor,models:[original,modified]});return}
 if(type==='notes'){body.innerHTML=`<textarea class="note-editor" aria-label="Markdown notes">${escape(ws().notes)}</textarea>`;$('.note-editor',body).addEventListener('input',e=>{ws().notes=e.target.value;persist()});return}
 if(type==='todos'){body.innerHTML=`<div class="todo-list">${ws().todos.map((t,i)=>`<label><input type="checkbox" data-todo="${i}" ${t.done?'checked':''}><span>${escape(t.text)}</span></label>`).join('')}<form class="todo-add"><input aria-label="New to-do" placeholder="Add a to-do…" required maxlength="300"><button class="outline">Add</button></form><button class="quiet" data-action="download-todos">↓ Download .md</button></div>`;$('.todo-add',body).addEventListener('submit',e=>{e.preventDefault();ws().todos.push({text:$('input',e.target).value,done:false});render()});return}
 if(type==='files'){body.innerHTML=`<div style="padding:12px">${Object.keys(ws().files).map(name=>`<button class="file" data-file="${escape(name)}"><span class="file-icon">▤</span><span>${escape(name)}</span></button>`).join('')}<button class="outline" data-action="upload" style="margin:12px 5px">＋ Import from your computer</button></div>`;return}
 if(type==='pdf'){body.classList.add('editor-body');const file=ws().pdfFile||'sample-paper.pdf';body.innerHTML=`<div class="pdf-toolbar"><span>${escape(file)}</span><button data-action="pdf-selection">Add to chat</button><button data-action="upload">Open PDF…</button><select data-pdf-scale aria-label="PDF zoom"><option value="1">Fit width</option><option value="1.25">125%</option><option value="1.5">150%</option></select></div><div class="pdf-pages"><div class="panel-error">Loading all pages…</div></div>`;await renderPDF(el,file,1,generation);return}
 if(type==='board'){body.innerHTML=boardHTML();return}
